import {books,profiles,me as demoMe,seedChat,nextDemoLine,strings} from './copy.mjs';
import {classifySwipe} from './interaction.mjs';
import {createDemoState,like,sendMessage,getMatch,getRevealView,consentPhoto,revokeConsent,changePhoto,block,unmatch,canViewPhoto} from './domain.mjs';

// This is a fictional, in-memory product demonstration. No authentication,
// payment, real messaging, photo protection or identity verification is provided.
const me=structuredClone(demoMe);
const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const iconNames={discover:'books',connections:'heart',chat:'chat-circle-dots',profile:'user-circle',heart:'heart',arrow:'arrow-right',lock:'lock-key',filter:'sliders-horizontal',book:'books',close:'x',send:'paper-plane-tilt',check:'check',rewind:'arrow-counter-clockwise',back:'arrow-left',more:'dots-three',chevron:'caret-right',info:'info'};
const icon=name=>`<svg viewBox="0 0 256 256" fill="currentColor" aria-hidden="true"><use href="./assets/v3/icons.svg#${iconNames[name]??'books'}"></use></svg>`;
const state=createDemoState({userIds:['you',...profiles.map(x=>x.id)],waitMs:86400000,turnsRequired:5});
let now=Date.now(),seq=0,currentView='discover',activePerson='lia',currentIndex=0,genre='Tudo',city='São Paulo',ageMin=18,ageMax=65,paused=false,passed=new Set(),saved=new Set(),reports=[];
let referenceData=[];
let bookIndex=0,historyActions=[],preview=true,drag=null,suppressClickUntil=0,pendingSetting=null;
const drafts={},scrollPositions={},threadScroll={};
let scrollBottomPerson=null,discoveryMode='for-you',detailPerson=null,navigationParent=null,expandedBook=null;
me.relationship='Monogamia';me.interest='Todos';
const bgColors={estrela:'#d8cfb5',avesso:'#a84132',torto:'#67705e',rio:'#d0d4d5',vegetariana:'#414340',cegueira:'#e0d8cb'};
const notify=s=>{ $('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').classList.remove('show'),4800); };
const msg=(id,from,text)=>sendMessage(state,id,from,text,++now,`demo-${++seq}`);
for(const person of profiles) if(person.id==='ana'||person.id==='lia')like(state,person.id,'you',now);
const initial=like(state,'you','lia',now);
for(const line of seedChat)msg(initial.id,line.from,line.text);
const activeMatches=()=>state.matches.filter(m=>m.status==='ACTIVE');
const personFor=m=>profiles.find(p=>m.users.includes(p.id));
const getPerson=id=>profiles.find(x=>x.id===id);
const affinityFor=p=>{const shared=p.books.filter(id=>me.books.includes(id)).map(id=>books.find(b=>b.id===id).title);return shared.length?strings.sharedBooks(shared):strings.noSharedBooks;};
const filtered=()=>profiles.filter(x=>x.id!=='lia'&&x.city===city&&x.age>=ageMin&&x.age<=ageMax&&(genre==='Tudo'||x.category===genre)&&!passed.has(x.id)&&!state.likes.some(([a,b])=>a==='you'&&b===x.id)&&!state.blocks.some(([a,b])=>a===x.id||b===x.id));
const bookHtml=(id,caption='')=>{const b=books.find(x=>x.id===id);return `<div class="book-item"><button data-action="book" data-id="${b.id}" aria-label="Conhecer a opinião sobre ${esc(b.title)}"><img src="./assets/cover-${b.id}.svg" width="200" height="300" alt="Capa conceitual de ${esc(b.title)}"><p>${caption?`<span class="mini-caption">${esc(caption)}</span>`:''}${esc(b.author)}</p></button></div>`;};
const lockArt=()=>`<div class="lock-illustration" aria-hidden="true"><div class="margin-lines"><span></span><span></span><span></span><span></span><span></span></div>${icon('lock')}</div>`;
const portrait=(id)=>{const variant=id==='you'?0:profiles.findIndex(p=>p.id===id)+1;const hair=variant%2?'<path d="M49 91c-15-56 8-74 34-74 34 0 44 27 30 78-7-12-12-30-17-43-8 15-26 15-47 16Z" fill="#333333"/>':'<path d="M49 59c-1-42 64-56 68 3l-24-21-38 30Z" fill="#333333"/>';return `<svg role="img" aria-label="Retrato ilustrativo de personagem fictício" viewBox="0 0 170 190"><path d="M10 190c5-59 33-70 75-70s71 11 75 70" fill="${variant%2?'#a84132':'#51565b'}"/><path d="M71 114v22c12 14 20 14 31 0v-22" fill="#cbb3a1"/><ellipse cx="85" cy="80" rx="34" ry="44" fill="#dcc5b3"/>${hair}<path d="M66 80h8m23 0h8m-24 24q8 6 15-2" fill="none" stroke="#434343" stroke-width="2.6" stroke-linecap="round"/></svg>`;};

const avatar=(p,cls='')=>`<span class="book-avatar ${cls}"><img src="./assets/cover-${p.books[0]}.svg" alt="Livro escolhido por ${esc(p.name)}"></span>`;
const btn=(action,label,ic,cls='',id='')=>`<button class="icon-button ${cls}" data-action="${action}" data-id="${id}" aria-label="${label}" title="${label}">${icon(ic)}</button>`;
const title=(text,extra='')=>extra?`<div class="screen-meta">${extra}</div>`:'';
function header(){
 const inThread=currentView==='chat'&&activePerson,detail=currentView==='people'||currentView==='profile'&&!preview;
 $('.app-shell').classList.toggle('dedicated-thread',Boolean(inThread));$('.topbar').hidden=Boolean(inThread);$('#nav').hidden=Boolean(inThread||detail);
 if(inThread)return;
 if(currentView==='people'){const p=getPerson(detailPerson);$('.topbar').innerHTML=`${btn('back-origin','Voltar à tela anterior','back')}<h1>${esc(p?.name??'Perfil')}</h1>${btn('safety','Opções deste perfil','more','',detailPerson)}`;return;}
 if(currentView==='profile'&&!preview){$('.topbar').innerHTML=`${btn('preview-mode','Voltar ao meu perfil','back')}<h1>Editar perfil</h1><button class="plain" data-action="preview-mode">Concluir</button>`;return;}
 const names={connections:'Curtidas',chat:'Conversas',profile:'Meu perfil',studio:'Projeto'};
 $('.topbar').innerHTML=currentView==='discover'?`<button class="brand" data-view="discover" aria-label="Trelelê, descobrir pessoas">${icon('book')}trelelê</button>${btn('filters','Preferências de descoberta','filter')}`:`<h1>${names[currentView]??'Trelelê'}</h1>${currentView==='profile'?btn('filters','Preferências de descoberta','filter'):currentView==='studio'?btn('back-origin','Voltar à tela anterior','back'):btn('how','Como as fotos são reveladas','info')}`;
}
function nav(){ $('#nav').innerHTML=[['discover','Descobrir','discover'],['connections','Curtidas','heart'],['chat','Conversas','chat'],['profile','Perfil','profile']].map(([view,label,ic])=>`<button class="nav-item ${currentView===view?'selected':''}" data-view="${view}" ${currentView===view?'aria-current="page"':''}>${icon(ic)}<span>${label}</span>${view==='chat'&&activeMatches().length?'<i></i>':''}</button>`).join(''); }
function render(focus=false){const oldLog=$('.messages'),oldPerson=$('[data-form="chat"]')?.dataset.person;if(oldLog&&oldPerson)threadScroll[oldPerson]=oldLog.scrollTop;if(currentView==='chat'&&activePerson&&getMatch(state,'you',activePerson)?.status!=='ACTIVE')activePerson=null;if(currentView==='people'&&!personAvailable(detailPerson)){currentView='discover';detailPerson=null;navigationParent=null;}header();const oldFocus=document.activeElement;const focusData=oldFocus?.dataset?.action?{...oldFocus.dataset}:null;nav();$('#main').className=`screen view-${currentView}${currentView==='chat'&&activePerson?' in-thread':''}${currentView==='discover'&&discoveryMode==='nearby'?' mode-nearby':''}`;$('#main').innerHTML=({discover,connections,chat,profile,studio,people}[currentView]??discover)();if(focus)$('#main').focus({preventScroll:true});else if(focusData){const replacement=[...$('#main').querySelectorAll('[data-action]')].find(el=>Object.entries(focusData).every(([key,value])=>el.dataset[key]===value));(replacement??$('#main')).focus({preventScroll:true});}if(currentView==='chat'&&activePerson){const log=$('.messages');if(log){log.scrollTop=scrollBottomPerson===activePerson||threadScroll[activePerson]===undefined?log.scrollHeight:threadScroll[activePerson];if(scrollBottomPerson===activePerson)scrollBottomPerson=null;}}const actions=$('#screen-actions');actions.hidden=currentView!=='people';actions.innerHTML=currentView==='people'?peopleActions():'';document.title=`Trelelê · ${{discover:'Descobrir',connections:'Curtidas',chat:'Conversas',profile:'Perfil',studio:'Projeto',people:getPerson(detailPerson)?.name??'Perfil'}[currentView]??'Encontros por livros'}`;}
function currentRoute(){return {view:currentView,person:currentView==='people'?detailPerson:currentView==='chat'?activePerson:null,mode:discoveryMode,edit:currentView==='profile'&&!preview};}
function hashFor(route){if(route.view==='discover')return `#discover/${route.mode==='nearby'?'nearby':'for-you'}`;if(route.view==='people')return `#people/${route.person}`;if(route.view==='chat'&&route.person)return `#chat/${route.person}`;if(route.view==='profile'&&route.edit)return '#profile/edit';return `#${route.view}`;}
function parseHash(){const [view,id]=location.hash.slice(1).split('/');if(view==='people')return personAvailable(id)?{view,person:id}:{view:'discover',mode:'for-you'};if(view==='chat')return {view,person:getPerson(id)&&getMatch(state,'you',id)?.status==='ACTIVE'?id:null};if(view==='discover')return {view,mode:id==='nearby'?'nearby':'for-you'};return {view:['connections','profile','studio'].includes(view)?view:'discover',edit:view==='profile'&&id==='edit'};}
function personAvailable(id){return Boolean(getPerson(id))&&!state.blocks.some(pair=>pair.includes(id))&&!['UNMATCHED','BLOCKED'].includes(getMatch(state,'you',id)?.status);}
function captureContext(){const route=currentRoute(),log=$('.messages');return {route,parent:navigationParent,bookIndex,rootScroll:$('#main').scrollTop,messagesScroll:log?.scrollTop??null,focusKey:document.activeElement?.dataset?{...document.activeElement.dataset}:null};}
function routeRecord(pushed=false){return {treleleRoute:currentRoute(),treleleParent:navigationParent,trelelePushed:pushed,treleleBookIndex:bookIndex,treleleScroll:scrollPositions[routeHash()]??0};}
function applyRoute(route,parent=null){if(route.view==='people'&&!personAvailable(route.person)){route={view:'discover',mode:'for-you'};parent=null;}if(route.view==='chat'&&route.person&&getMatch(state,'you',route.person)?.status!=='ACTIVE')route={view:'chat',person:null};currentView=route.view;discoveryMode=route.mode??discoveryMode;detailPerson=route.view==='people'?route.person:null;activePerson=route.view==='chat'?route.person??null:activePerson;preview=route.view==='profile'?!route.edit:preview;navigationParent=parent;}
function savePosition(){scrollPositions[routeHash()]=$('#main').scrollTop;const person=$('[data-form="chat"]')?.dataset.person,log=$('.messages');if(person&&log)threadScroll[person]=log.scrollTop;}
function navigate(view,person=null,push=true,options={}){
 const parent=options.parent??((view==='people'||view==='studio'||view==='profile'&&options.edit)?captureContext():null);
 const origin=captureContext();if($('#dialog').open)closeDialog();savePosition();if(push){historyTask(()=>history.replaceState({...history.state,treleleRoute:origin.route,treleleParent:origin.parent,treleleBookIndex:origin.bookIndex,treleleScroll:origin.rootScroll},'',hashFor(origin.route)));}
 const next={view:['discover','connections','chat','profile','studio','people'].includes(view)?view:'discover',person,mode:options.mode??discoveryMode,edit:Boolean(options.edit)};
 applyRoute(next,parent);const hash=routeHash(),record=routeRecord(push);
 if(push)historyTask(()=>{if(location.hash!==hash)history.pushState(record,'',hash);else history.replaceState(record,'',hash);});
 render(true);$('#main').scrollTop=options.scroll??scrollPositions[hash]??0;
}
function go(view){navigate(view,null);}
function restoreFocus(context){
 const key=context?.focusKey;if(!key||!Object.keys(key).length||document.activeElement?.matches('input,textarea,[contenteditable="true"]'))return;
 const target=[...$('#main').querySelectorAll('button[data-action],button[data-view],a[data-view]')].find(element=>Object.entries(key).every(([name,value])=>element.dataset[name]===value));
 if(target&&!target.disabled&&!target.closest('[hidden]'))target.focus({preventScroll:true});
}
function restoreOrigin(consume=true){
 const context=navigationParent??{route:{view:'discover',mode:'for-you'},parent:null,bookIndex:0,rootScroll:0};
 const canConsume=consume&&Boolean(history.state?.trelelePushed)&&Boolean(navigationParent);
 if($('#dialog').open)closeDialog();savePosition();bookIndex=context.bookIndex??bookIndex;if(context.route.view==='chat'&&context.route.person&&context.messagesScroll!==null)threadScroll[context.route.person]=context.messagesScroll;
 applyRoute(context.route,context.parent??null);render(true);$('#main').scrollTop=context.rootScroll??0;restoreFocus(context);
 if(canConsume)historyTask(()=>traverseHistory(-1));else{const hash=routeHash(),record=routeRecord(false);historyTask(()=>history.replaceState(record,'',hash));}
}
function route(){applyRoute(parseHash(),null);render(true);history.replaceState(routeRecord(false),'',routeHash());}
function currentPerson(){return filtered()[0];}
function deck(){const p=currentPerson();return `${paused?`<div class="empty-state"><span class="empty-icon">${icon('profile')}</span><h1>Você pausou a descoberta</h1><p>A descoberta está pausada.</p><button class="primary" data-action="pause">Retomar</button></div>`:p?`<div class="deck" aria-label="Pessoas para conhecer"><div class="back-card back-two"></div><div class="back-card back-one"></div><article class="swipe-card" data-person="${p.id}" data-person-id="${p.id}" aria-label="Perfil de ${p.name}. Arraste para curtir ou passar."><div class="card-media" style="--book-color:${bgColors[p.books[bookIndex]]}"><div class="book-progress" aria-label="Livros de ${p.name}">${p.books.map((id,i)=>`<button data-action="book-index" data-index="${i}" aria-label="Ver livro ${i+1} de ${p.books.length}: ${esc(books.find(b=>b.id===id).title)}" aria-pressed="${i===bookIndex}" class="${i===bookIndex?'active':''}"><span></span></button>`).join('')}</div><span class="book-counter">${bookIndex+1} de ${p.books.length}</span><span class="private-tag">${icon('lock')} Foto oculta</span><div class="cover-stage"><img class="main-book" src="./assets/cover-${p.books[bookIndex]}.svg" draggable="false" alt="Capa conceitual de ${esc(books.find(b=>b.id===p.books[bookIndex]).title)}"></div><span class="book-caption">Na estante de ${p.name}</span><div class="gesture-label label-like" aria-hidden="true">CURTIR</div><div class="gesture-label label-pass" aria-hidden="true">PASSAR</div><div class="media-tap-hint"><span>${icon('back')}</span><small>Toque nos lados para ver os livros</small><span>${icon('chevron')}</span></div></div><div class="card-info" data-action="person" data-id="${p.id}"><button class="info-open" data-action="person" data-id="${p.id}" aria-label="Abrir perfil completo de ${p.name}"><span><strong>${p.name}<b>, ${p.age}</b></strong><small>${p.city} · ${p.intent}</small></span><span class="info-circle">${icon('info')}</span></button><p class="card-quote">${esc(p.bookOpinions?.[p.books[bookIndex]]??p.quote)}</p><span class="affinity-chip">${icon('book')}${p.books.filter(id=>me.books.includes(id)).length} livros em comum</span></div></article></div><div class="decision-actions">${btn('rewind','Voltar à última pessoa','rewind','rewind')}${btn('pass','Passar pessoa','close','pass',p.id)}${btn('like','Curtir pessoa','heart','like',p.id)}</div>`:`<div class="empty-state"><span class="empty-icon">${icon('book')}</span><h1>Não há mais perfis por aqui</h1><p>Não há outros perfis fictícios com essas preferências.</p><button class="primary" data-action="reset-passes">Rever pessoas</button><button class="plain" data-action="filters">Ajustar filtros</button></div>`}`;}
function discover(){return `<div class="discover-segments" role="group" aria-label="Modo de descoberta"><button data-action="discovery-mode" data-mode="for-you" aria-pressed="${discoveryMode==='for-you'}">Para você</button><button data-action="discovery-mode" data-mode="nearby" aria-pressed="${discoveryMode==='nearby'}">Por perto</button></div>${discoveryMode==='nearby'?nearby():deck()}`;}
function nearby(){if(paused)return `<div class="empty-state"><h2>Descoberta pausada</h2><p>Suas conversas continuam abertas.</p><button class="primary" data-action="pause">Retomar</button></div>`;const list=filtered();return `<div class="nearby-heading"><div><h2>${esc(city)}</h2><p>Cidade do cenário fictício · sem usar sua localização</p></div>${btn('filters','Mudar cidade e filtros','filter')}</div><div class="nearby-grid">${list.map(p=>`<button class="nearby-person" data-action="person" data-id="${p.id}" aria-label="Conhecer ${p.name}, ${p.age}, ${p.city}"><span class="nearby-art" style="--book-color:${bgColors[p.books[0]]}"><img src="./assets/cover-${p.books[0]}.svg" alt="Livro escolhido por ${p.name}"><span>${icon('lock')} Foto oculta</span></span><span class="nearby-identity"><strong>${p.name}, ${p.age}</strong><small>${p.city}</small><span>${p.intent}</span></span></button>`).join('')||'<div class="empty-state compact"><h2>Não há outros perfis aqui</h2><p>Você pode ajustar os filtros do teste.</p><button class="primary" data-action="filters">Ajustar filtros</button></div>'}</div><p class="privacy-note">Toque em um perfil para conhecer a pessoa. Isso não envia uma curtida.</p>`;}
function people(){const p=getPerson(detailPerson);if(!p)return '';const cover=p.books[Math.min(navigationParent?.bookIndex??0,p.books.length-1)];return `<article class="person-page" data-person-id="${p.id}"><div class="person-cover" style="--book-color:${bgColors[cover]}"><img src="./assets/cover-${cover}.svg" alt="Livro escolhido por ${p.name}"><span>${icon('lock')} Foto oculta</span></div><section class="person-intro"><h1>${p.name}, ${p.age}</h1><p>${p.city}</p><span class="person-intent">${p.intent}</span><p class="person-bio">${esc(p.note)}</p></section><section class="person-books"><h2>Os livros de ${p.name}</h2><p class="muted">Toque para ler o que achou.</p>${p.books.map(id=>{const b=books.find(x=>x.id===id),open=expandedBook===id;return `<div class="person-book"><button data-action="book" data-id="${id}" data-person="${p.id}" aria-expanded="${open}" aria-controls="opinion-${id}"><img src="./assets/cover-${id}.svg" alt=""><span><strong>${esc(b.title)}</strong><small>${esc(b.author)}</small></span>${icon(open?'close':'chevron')}</button><div class="${open?'book-opinion':'book-opinion-panel'}" id="opinion-${id}" ${open?'':'hidden'}><p>“${esc(p.bookOpinions?.[id]??p.quote)}”</p><button class="plain" data-action="book" data-id="${id}" data-person="${p.id}">Recolher opinião</button></div></div>`;}).join('')}</section><p class="person-affinity">${icon('book')}${esc(affinityFor(p))}</p><button class="person-safety" data-action="safety" data-id="${p.id}">Bloquear ou denunciar ${icon('chevron')}</button></article>`;}
function peopleActions(){const p=getPerson(detailPerson);if(!p)return '';const match=getMatch(state,'you',p.id),sent=state.likes.some(([a,b])=>a==='you'&&b===p.id);if(match?.status==='ACTIVE')return `<button class="primary" data-action="open-chat" data-id="${p.id}">${icon('chat')} Abrir conversa</button>`;if(sent)return `<div class="sent-confirmation">${icon('check')} Curtida enviada</div>`;return `<button class="detail-pass" data-action="pass" data-id="${p.id}">${icon('close')} Passar</button><button class="primary" data-action="like" data-id="${p.id}">${icon('heart')} Curtir ${p.name}</button>`;}
function connections(){const received=profiles.filter(p=>state.likes.some(([a,b])=>a===p.id&&b==='you')&&!getMatch(state,'you',p.id)&&!state.blocks.some(pair=>pair.includes(p.id)));const sent=profiles.filter(p=>state.likes.some(([a,b])=>a==='you'&&b===p.id)&&!getMatch(state,'you',p.id)&&!state.blocks.some(pair=>pair.includes(p.id)));return `${title('Curtidas',`<span class="count">${received.length}</span>`)}<p class="screen-description">Quem curtiu seu perfil.<br>As fotos continuam ocultas.</p><div class="likes-grid">${received.map(p=>`<button class="literary-tile" data-action="person" data-id="${p.id}" style="--book-color:${bgColors[p.books[0]]}"><img src="./assets/cover-${p.books[0]}.svg" alt="Livro escolhido por ${p.name}"><span class="tile-lock">${icon('lock')}</span><span class="tile-info"><strong>${p.name}, ${p.age}</strong><small>${p.books.filter(id=>me.books.includes(id)).length} livros em comum</small></span></button>`).join('')||'<div class="empty-state compact"><h2>Você ainda não recebeu curtidas</h2><p>As curtidas recebidas aparecem aqui.</p><button class="primary" data-view="discover">Descobrir pessoas</button></div>'}</div><h2 class="section-label">Curtidas que você enviou <span>${sent.length}</span></h2>${sent.map(p=>`<button class="person-row" data-action="person" data-id="${p.id}">${avatar(p)}<div><strong>${p.name}, ${p.age}</strong><small>Ainda não deu match</small></div>${icon('heart')}</button>`).join('')||'<p class="muted section-copy">Curta alguém para começar.</p>'}<p class="privacy-note">${icon('lock')} A foto só aparece se os dois quiserem.</p>`;}
function inbox(){const matches=activeMatches(),newMatches=matches.filter(m=>m.messages.length===0),threads=matches.filter(m=>m.messages.length>0);return `${title('Conversas')}<h2 class="section-label">Novos matches <span>${newMatches.length}</span></h2><div class="new-matches">${newMatches.map(m=>{const p=personFor(m);return `<button data-action="open-chat" data-id="${p.id}">${avatar(p,'new-match')}<strong>${p.name}</strong></button>`;}).join('')||'<p class="muted">Seus próximos matches aparecem aqui.</p>'}</div><h2 class="section-label">Mensagens</h2><div class="chat-list">${threads.map(m=>{const p=personFor(m),last=m.messages.at(-1);return `<button class="chat-row" data-action="open-chat" data-id="${p.id}">${avatar(p)}<span><strong>${p.name}<small>${last?'Agora':'Novo match'}</small></strong><p>${last?esc((last.from==='you'?'Você: ':'')+last.text):'Vocês deram match. Que tal mandar um oi?'}</p></span><i class="unread-dot"></i></button>`;}).join('')||'<div class="empty-state compact"><h2>Nenhuma conversa por enquanto</h2><button class="primary" data-view="discover">Encontrar alguém</button></div>'}</div>`;}
function chat(){if(!activePerson)return inbox();const p=getPerson(activePerson),m=p&&getMatch(state,'you',p.id);if(!m||m.status!=='ACTIVE'){activePerson=null;return inbox();}const rv=getRevealView(state,m.id,'you',now),revealed=canViewPhoto(state,m.id,'you',p.id,now);return `<div class="thread"><div class="thread-header">${btn('inbox','Voltar para conversas','back')}${avatar(p)}<button class="thread-person" data-action="person" data-id="${p.id}"><strong>${p.name}</strong><small>${revealed?'Ilustrações reveladas':'Foto oculta'}</small></button>${btn('safety','Segurança e opções','more','',p.id)}</div><div class="messages" role="log" aria-live="polite" aria-label="Conversa fictícia"><p class="chat-date">Conversa de teste</p><div class="starter"><img src="./assets/cover-${p.books[0]}.svg" alt=""><p>${esc(affinityFor(p))}</p></div>${m.messages.map(x=>`<div class="message ${x.from==='you'?'own':''}"><p>${esc(x.text)}</p><small>${x.from==='you'?'Você':'Perfil de teste'}</small></div>`).join('')}<section class="reveal-card">${revealed?`<div class="two-portraits"><div>${portrait('you')}<small>Você · ilustração</small></div><div>${portrait(p.id)}<small>${p.name} · ilustração</small></div></div><h3>Fotos liberadas</h3><p>Retratos ilustrativos, sem foto real.</p><button class="plain" data-action="revoke">Deixar de mostrar minha foto</button>`:`${icon('lock')}<h3>${rv.status==='ELIGIBLE'?'Quer mostrar sua foto?':'A foto ainda está oculta'}</h3><p>${rv.status==='ELIGIBLE'?(rv.ownConsent?strings.revealAcceptedBody:strings.revealReadyBody):'A foto continua oculta. Vocês podem escolher mostrar depois de conversar.'}</p>${rv.status==='ELIGIBLE'?`<button class="primary" data-action="consent" ${rv.ownConsent?'disabled':''}>${rv.ownConsent?'Você escolheu mostrar':'Quero mostrar minha foto'}</button>${rv.ownConsent?'<button class="plain" data-action="revoke">Mudei de ideia</button>':''}`:'<button class="plain" data-action="how">Quando a foto aparece?</button>'}`}</section></div><form data-form="chat" data-person="${p.id}" class="composer"><label class="sr-only" for="message">Mensagem fictícia, nada será enviado</label><input id="message" name="message" maxlength="2000" placeholder="${strings.composer}" value="${esc(drafts[p.id]??'')}" autocomplete="off" required><button type="submit" aria-label="Adicionar mensagem na demonstração">${icon('send')}</button></form></div>`;}
function profile(){return `${title('Meu perfil')}${preview?`<div class="preview-card"><div class="preview-books">${me.books.map(id=>`<img src="./assets/cover-${id}.svg" alt="${esc(books.find(b=>b.id===id).title)}">`).join('')}</div><h2>${esc(me.name)}, ${me.age}</h2><p>${esc(me.city)}</p><span class="pill">${esc(me.relationship)}</span><p>${esc(me.bio)}</p><small>Seu perfil na descoberta</small></div><div class="profile-overview-actions"><button class="primary" data-action="edit-mode">Editar perfil</button><button class="settings-row" data-action="filters"><span>Preferências de descoberta</span>${icon('chevron')}</button><button class="settings-row" data-action="pause" role="switch" aria-checked="${paused}"><span>Pausar descoberta</span><span>${paused?'Ativada':'Desativada'}</span></button></div>`:`<div class="profile-intro">${avatar(me)}<div><h2>${esc(me.name)}, ${me.age}</h2><p>Seus livros aparecem no lugar da foto.</p></div></div><div class="settings-group"><h2>Sobre você</h2><button class="settings-row" data-action="edit-bio"><span>Nome e apresentação</span><span>Editar ${icon('chevron')}</span></button><button class="settings-row" data-action="select-setting" data-key="intent"><span>Intenção</span><span>${esc(me.intent)} ${icon('chevron')}</span></button><button class="settings-row" data-action="select-setting" data-key="relationship"><span>Tipo de relacionamento</span><span>${esc(me.relationship)} ${icon('chevron')}</span></button><button class="settings-row" data-action="select-setting" data-key="interest"><span>Me interesso por</span><span>${esc(me.interest)} ${icon('chevron')}</span></button></div><div class="settings-group"><h2>Meus livros <small>${me.books.length}/5</small></h2><p class="muted">Toque para escolher seus livros.</p><div class="edit-books">${books.map(b=>`<button data-action="toggle-book" data-id="${b.id}" aria-pressed="${me.books.includes(b.id)}"><img src="./assets/cover-${b.id}.svg" alt="${esc(b.title)}"><span>${icon(me.books.includes(b.id)?'check':'book')}</span></button>`).join('')}</div></div><div class="settings-group"><h2>Preferências de descoberta</h2><button class="settings-row" data-action="filters"><span>Cidade e idade</span><span>${city} ${icon('chevron')}</span></button><button class="settings-row" data-action="pause" role="switch" aria-checked="${paused}" aria-label="Pausar descoberta"><span>Pausar descoberta</span><span class="toggle ${paused?'on':''}" aria-label="${paused?'Ativada':'Desativada'}"></span></button></div><button class="settings-row" data-action="reports"><span>Denúncias de teste</span>${icon('chevron')}</button><button class="settings-row danger" data-action="reset"><span>Recomeçar o teste</span>${icon('chevron')}</button>`}<p class="privacy-note">Perfil de teste · perfil fictício.</p>`;}
function studio(){return `${title('Estúdio',btn('back-profile','Voltar ao perfil','back'))}<p class="screen-description">Projeto e acervo da demonstração. As referências de navegação guiam o fluxo; os livros ocupam o lugar das fotos.</p><a class="settings-row" href="./pesquisa.html" target="_blank" rel="noopener">Telas e fluxos: Happn × Tinder ${icon('arrow')}</a><h2 class="section-label">Referências e ativos</h2><div class="studio-cover">${books.slice(0,3).map(b=>`<img src="./assets/cover-${b.id}.svg" alt="Capa conceitual de ${esc(b.title)}">`).join('')}</div><p class="section-copy">Capas conceituais originais. Retratos em SVG são ilustrações fictícias, geradas apenas após a simulação de consentimento. Nenhuma imagem de banco representa uma pessoa do aplicativo.</p><a class="settings-row" href="./assets/asset-manifest.json" target="_blank" rel="noopener">Manifesto de ativos ${icon('arrow')}</a><a class="settings-row" href="./assets/interaction-references.json" target="_blank" rel="noopener">Referências da dinâmica ${icon('arrow')}</a><h2 class="section-label">Documentos do projeto</h2>${[['FLUXOS-V4.md','Mapa das telas e retornos V4'],['HAPPN-V4.md','Pesquisa de telas Happn'],['TINDER-V4.md','Pesquisa de telas Tinder'],['CODIGO-PRIVACIDADE-V4.md','Código e privacidade V4'],['QA-V4.md','Jornadas verificadas V4'],['REFERENCIAS-V3.md','Referências externas V3'],['VOZ-V3.md','Textos e diálogos'],['DINAMICA-TINDER.md','Dinâmica do aplicativo'],['UX-V2.md','Experiência mobile V2'],['REFERENCIAS-INTERACAO.md','Referências de interação'],['PRODUTO-RECEITA.md','Produto e validação'],['ARQUITETURA.md','Arquitetura'],['SEGURANCA.md','Segurança e privacidade'],['UX-ACESSIBILIDADE.md','Experiência e acessibilidade'],['PLANO-QA.md','Plano de qualidade'],['REFERENCIAS-VISUAIS.md','Referências visuais'],['DESIGN.md','Design'],['VALIDACAO.md','Verificações']].map(([file,label])=>`<a class="settings-row" href="./docs/${file}" target="_blank" rel="noopener">${label} ${icon('arrow')}</a>`).join('')}<a class="primary download" href="./trelele-desenvolvimento.zip" download>Baixar pacote de desenvolvimento</a><p class="privacy-note">Demonstração estática. Não possui login, chat real ou proteção de fotografias. As regras no navegador são manipuláveis.</p>`;}

let returnFocus=null,modalFrames=[],modalSequence=0,ownedPop=null,historyBusy=false;
const modalSnapshots=new Map(),historyTasks=[];
// Serialize only URL/history mutations. UI updates remain synchronous. Closing
// a sheet consumes its actual entries before a following route or match is pushed.
function historyTask(task){historyTasks.push(task);void drainHistory();}
function drainHistory(){if(historyBusy)return;while(historyTasks.length){const result=historyTasks.shift()();if(result?.then){historyBusy=true;result.finally(()=>{historyBusy=false;drainHistory();});return;}}}
function traverseHistory(delta){return new Promise(resolve=>{ownedPop=resolve;try{history.go(delta);}catch{ownedPop=null;resolve();}});}
function routeHash(){return hashFor(currentRoute());}
function displayModal(frame){$('#dialog').className=frame.className;$('#dialog-content').innerHTML=`<div class="sheet-handle" aria-hidden="true"></div><div class="dialog-top"><h2 id="dialog-title">${frame.titleText}</h2>${btn('close','Fechar','close')}</div>${frame.body}${frame.actions?`<div class="dialog-actions">${frame.actions}</div>`:''}`;if(!$('#dialog').open)$('#dialog').showModal();}
function hideModalUI(){modalFrames=[];if($('#dialog').open)$('#dialog').close();}
function dialog(titleText,body,actions='',className='',nested=false){
  const frame={titleText,body,actions,className};
  returnFocus=document.activeElement;
  const wasOpen=modalFrames.length>0;
  if(wasOpen&&nested)modalFrames.push(frame);else if(wasOpen)modalFrames[modalFrames.length-1]=frame;else modalFrames=[frame];
  displayModal(frame);
  const snapshot=modalFrames.map(item=>({...item})),token=++modalSequence,hash=routeHash();
  modalSnapshots.set(token,snapshot);
  historyTask(()=>{const method=wasOpen&&!nested?'replaceState':'pushState';history[method]({...history.state,treleleModal:token},'',hash);});
}
function closeDialog(){const depth=modalFrames.length;if(!depth){if($('#dialog').open)$('#dialog').close();return;}hideModalUI();historyTask(()=>traverseHistory(-depth));}
function closeLayer(){if(!modalFrames.length){closeDialog();return;}modalFrames.pop();if(modalFrames.length)displayModal(modalFrames.at(-1));else if($('#dialog').open)$('#dialog').close();historyTask(()=>traverseHistory(-1));}
$('#dialog').addEventListener('cancel',event=>{event.preventDefault();closeLayer();});
$('#dialog').addEventListener('close',()=>{if(returnFocus?.isConnected)returnFocus.focus();else $('#main').focus({preventScroll:true});});
function showMatch(p){dialog('Deu match!',`<div class="match-content"><p>${strings.matchLine(p.name)}</p><div class="match-pair"><span>${avatar(me)}</span><b>${icon('heart')}</b><span>${avatar(p)}</span></div><p>${esc(affinityFor(p))}</p><small>Match de demonstração · ninguém real recebeu uma curtida</small></div>`,`<button class="primary" data-action="open-chat" data-id="${p.id}">Enviar mensagem</button><button class="outline" data-action="close">Continuar descobrindo</button>`,'match-overlay');}
function how(){dialog('Como funciona a foto',`<div class="sheet-body"><p>${strings.revealRule}</p><p>${strings.howBody}</p><p class="muted">Parâmetros experimentais. Nesta demo só existem ilustrações e dados fictícios; o navegador não protege fotos reais.</p></div>`,`<button class="primary" data-action="close">Entendi</button>`);}
function showPerson(id,trigger=null){if(!personAvailable(id)){notify('Este perfil não está disponível.');return;}const parent=captureContext();if(trigger)parent.focusKey={...trigger.dataset};expandedBook=null;navigate('people',id,true,{parent});}
function safety(id){dialog('Opções da conversa',`<p class="sheet-body">As ações abaixo valem apenas para os perfis de teste.</p><button class="settings-row danger" data-action="confirm-block" data-id="${id}">Bloquear perfil ${icon('chevron')}</button><button class="settings-row danger" data-action="report" data-id="${id}">Denúncia de teste ${icon('chevron')}</button>${getMatch(state,'you',id)?.status==='ACTIVE'?`<button class="settings-row" data-action="confirm-unmatch" data-id="${id}">Desfazer match ${icon('chevron')}</button>`:''}`);}
function decide(action,id){
 const p=getPerson(id);if(!p||!personAvailable(id))return;
 const fromProfile=currentView==='people',alreadySent=state.likes.some(([a,b])=>a==='you'&&b===id);
 if(action==='like'&&alreadySent){notify('Você já enviou uma curtida.');return;}
 let match=null;if(action==='like')match=like(state,'you',id,++now);else passed.add(id);
 historyActions.push({action,id});if(fromProfile&&navigationParent)navigationParent.bookIndex=0;bookIndex=0;closeDialog();
 if(fromProfile&&(action==='pass'||match))restoreOrigin(false);else render();
 if(match)showMatch(p);else notify(action==='like'?'Curtida enviada.':`Você passou ${p.name}.`);
}
function rewind(){const last=historyActions.at(-1);if(!last){notify('Você ainda não passou nenhum perfil.');return;}const match=getMatch(state,'you',last.id);if(match){notify('Vocês já deram match. A conversa está na aba Conversas.');return;}historyActions.pop();if(last.action==='pass')passed.delete(last.id);else state.likes=state.likes.filter(([a,b])=>!(a==='you'&&b===last.id));bookIndex=0;render();notify('O perfil anterior voltou.');}
function simulateConversation(){const m=getMatch(state,'you',activePerson),p=getPerson(activePerson);if(!m||m.status!=='ACTIVE')return;for(let i=0;i<12&&Object.values(getRevealView(state,m.id,'you',now).turns).some(x=>x<5);i++){const from=!m.messages.length?p.id:m.messages.at(-1).from==='you'?p.id:'you';const text=nextDemoLine(p.id,from,m.messages);if(!text)break;msg(m.id,from,text);}now=Math.max(now,(m.bilateralAt??now)+state.waitMs+1);scrollBottomPerson=activePerson;render();notify(strings.simulateDone);}
function filters(){dialog('Preferências de descoberta',`<form data-form="filters"><label for="filter-city">Cidade</label><select id="filter-city" name="city"><option ${city==='São Paulo'?'selected':''}>São Paulo</option><option ${city==='Rio de Janeiro'?'selected':''}>Rio de Janeiro</option></select><div class="field-grid"><div><label for="min-age">Idade mínima</label><input id="min-age" name="min" type="number" min="18" max="99" value="${ageMin}" required></div><div><label for="max-age">Idade máxima</label><input id="max-age" name="max" type="number" min="18" max="99" value="${ageMax}" required></div></div><label for="genre">Leituras</label><select id="genre" name="genre">${['Tudo','Ficção brasileira','Romance','Suspense'].map(g=>`<option ${genre===g?'selected':''}>${g}</option>`).join('')}</select><p class="muted">Filtros aplicados apenas aos personagens. Não usamos sua localização.</p><p class="error" id="filter-error" role="alert"></p><button class="primary" type="submit">Aplicar filtros</button></form>`);}
function setting(key){const values={intent:['Quero conhecer alguém','Quero namorar','Ainda não sei'],relationship:['Monogamia','Não monogamia ética','Prefiro conversar sobre isso'],interest:['Todos','Mulheres','Homens','Pessoas não binárias']};if(!values[key])return;pendingSetting={key,value:me[key]};dialog({intent:'O que você procura?',relationship:'Tipo de relacionamento',interest:'Me interesso por'}[key],`<p class="sheet-body muted">O que faz sentido para você?</p><div class="option-list">${values[key].map(v=>`<button data-action="set-setting" data-key="${key}" data-value="${esc(v)}" aria-pressed="${me[key]===v}"><span>${v}</span>${me[key]===v?icon('check'):''}</button>`).join('')}</div>`,`<button class="primary" data-action="apply-setting">Concluir</button><button class="plain" data-action="close">Cancelar</button>`);}
// Pointer capture is reserved for an intentional horizontal drag. Vertical
// movement cancels; tap navigation changes books, never the person.
document.addEventListener('pointerdown',event=>{const media=event.target.closest('.card-media');if(drag||!media||event.target.closest('button')||!event.isPrimary||event.button!==0)return;drag={pointerId:event.pointerId,card:media.closest('.swipe-card'),media,startX:event.clientX,startY:event.clientY,start:performance.now(),dx:0,dy:0,horizontal:false,vertical:false};});
document.addEventListener('pointermove',event=>{if(!drag||drag.pointerId!==event.pointerId)return;drag.dx=event.clientX-drag.startX;drag.dy=event.clientY-drag.startY;if(!drag.horizontal&&!drag.vertical&&Math.hypot(drag.dx,drag.dy)>12){if(Math.abs(drag.dx)>Math.abs(drag.dy)*1.35){drag.horizontal=true;drag.media.setPointerCapture?.(event.pointerId);}else if(Math.abs(drag.dy)>Math.abs(drag.dx)*1.1)drag.vertical=true;}if(drag.vertical)return;if(drag.horizontal){event.preventDefault();drag.card.classList.add('dragging');drag.card.style.transform=`translateX(${drag.dx}px) rotate(${drag.dx/22}deg)`;drag.card.style.setProperty('--like-opacity',String(Math.min(1,Math.max(0,drag.dx)/80)));drag.card.style.setProperty('--pass-opacity',String(Math.min(1,Math.max(0,-drag.dx)/80)));}}, {passive:false});
function endDrag(event,cancel=false){if(!drag||drag.pointerId!==event.pointerId)return;const d=drag;drag=null;d.card.classList.remove('dragging');d.card.style.transform='';d.card.style.setProperty('--like-opacity','0');d.card.style.setProperty('--pass-opacity','0');if(d.horizontal||d.vertical||Math.hypot(d.dx,d.dy)>12)suppressClickUntil=performance.now()+400;if(cancel||d.vertical||!d.card.isConnected||d.card.dataset.person!==currentPerson()?.id||currentView!=='discover')return;if(d.horizontal){const decision=classifySwipe({dx:d.dx,dy:d.dy,width:d.card.getBoundingClientRect().width,durationMs:performance.now()-d.start});if(decision==='like'||decision==='pass'){decide(decision,d.card.dataset.person);}return;}if(Math.hypot(d.dx,d.dy)<12){bookIndex=(bookIndex+(event.clientX-d.media.getBoundingClientRect().left>d.media.clientWidth/2?1:-1)+currentPerson().books.length)%currentPerson().books.length;render();suppressClickUntil=performance.now()+400;}}
document.addEventListener('lostpointercapture',event=>endDrag(event,true));
document.addEventListener('pointerup',event=>endDrag(event));document.addEventListener('pointercancel',event=>endDrag(event,true));
document.addEventListener('click',event=>{if(performance.now()<suppressClickUntil&&event.detail>0){event.preventDefault();event.stopImmediatePropagation();return;}const b=event.target.closest('[data-action],[data-view]');if(!b)return;if(b.dataset.view){go(b.dataset.view);return;}const action=b.dataset.action,id=b.dataset.id;try{switch(action){
case 'close':closeLayer();break;
case 'filters':filters();break;
case 'how':how();break;
case 'person':showPerson(id,b);break;
case 'discovery-mode':navigate('discover',null,true,{mode:b.dataset.mode});break;
case 'book-index':bookIndex=Number(b.dataset.index);render();break;
case 'like':case 'pass':decide(action,id);break;
case 'rewind':rewind();break;
case 'reset-passes':passed.clear();genre='Tudo';bookIndex=0;render();break;
case 'open-chat':closeDialog();navigate('chat',id,true,{parent:{route:{view:'chat',person:null},parent:null,rootScroll:0}});break;
case 'inbox':navigate('chat',null,false);historyTask(()=>history.replaceState(routeRecord(false),'','#chat'));break;
case 'simulate-reply':{closeDialog();const m=getMatch(state,'you',activePerson);const text=nextDemoLine(activePerson,activePerson,m.messages);if(text){msg(m.id,activePerson,text);scrollBottomPerson=activePerson;}else notify('Este perfil já usou todas as respostas do teste.');render();break;}
case 'simulate-conversation':closeDialog();simulateConversation();break;
case 'consent':{const m=getMatch(state,'you',activePerson);consentPhoto(state,m.id,'you',now,getRevealView(state,m.id,'you',now).photoVersions);render();notify('Você escolheu mostrar em privado nesta simulação.');break;}
case 'simulate-consent':{closeDialog();const m=getMatch(state,'you',activePerson);consentPhoto(state,m.id,activePerson,now);render();notify('A escolha do outro perfil foi simulada.');break;}
case 'revoke':revokeConsent(state,getMatch(state,'you',activePerson).id,'you');render();notify('A imagem não aparece mais aqui. Isso não apaga o que a outra pessoa já viu.');break;
case 'change-photo':closeDialog();changePhoto(state,activePerson);render();notify('A imagem mudou. Os dois precisam escolher mostrar de novo.');break;
case 'safety':safety(id);break;
case 'confirm-block':dialog('Bloquear perfil?',`<p class="sheet-body">A conversa será interrompida apenas nesta demonstração.</p>`,`<button class="primary" data-action="block" data-id="${id}">Bloquear no cenário</button><button class="plain" data-action="close">Cancelar</button>`,'',true);break;
case 'block':block(state,'you',id);closeDialog();activePerson=null;go('chat');notify('Personagem bloqueado na demo.');break;
case 'confirm-unmatch':dialog('Desfazer este match?',`<p class="sheet-body">Você não poderá retomar a conversa neste cenário.</p>`,`<button class="primary" data-action="unmatch" data-id="${id}">Desfazer match</button><button class="plain" data-action="close">Cancelar</button>`,'',true);break;
case 'unmatch':unmatch(state,getMatch(state,'you',id).id,'you');closeDialog();go('chat');notify('Conexão encerrada.');break;
case 'report':dialog('Denúncia de teste',`<form data-form="report" data-id="${id}"><p>Não é um canal de atendimento real. Não insira dados pessoais.</p><label for="reason">Motivo</label><select id="reason" name="reason"><option>Pressão para revelar</option><option>Assédio</option><option>Suspeita de perfil falso ou menor</option><option>Outro comportamento</option></select><label class="checkbox"><input type="checkbox" name="block" checked>Bloquear este perfil também</label><button class="primary" type="submit">Salvar neste teste</button></form>`,'','',true);break;
case 'reports':dialog('Registros da demonstração',`<div class="sheet-body"><p>Nenhum registro é enviado para uma equipe.</p>${reports.length?reports.map(r=>`<p>${esc(getPerson(r.id).name)} · ${esc(r.reason)}</p>`).join(''):'<p class="muted">Nenhum registro neste cenário.</p>'}${state.matches.filter(m=>m.status!=='ACTIVE').map(m=>{const p=personFor(m);return `<button class="plain" data-action="report" data-id="${p.id}">Denunciar cenário com ${p.name}</button>`;}).join('')}</div>`);break;
case 'edit-mode':navigate('profile',null,true,{edit:true});break;
case 'preview-mode':if(currentView==='profile'&&!preview)restoreOrigin();else navigate('profile');break;
case 'select-setting':setting(b.dataset.key);break;
case 'set-setting':if(pendingSetting?.key===b.dataset.key){pendingSetting.value=b.dataset.value;for(const option of document.querySelectorAll('[data-action="set-setting"]')){const selected=option.dataset.value===pendingSetting.value;option.setAttribute('aria-pressed',String(selected));option.innerHTML=`<span>${esc(option.dataset.value)}</span>${selected?icon('check'):''}`;}}break;
case 'apply-setting':if(pendingSetting){me[pendingSetting.key]=pendingSetting.value;pendingSetting=null;}closeDialog();render();break;
case 'edit-bio':dialog('Sua apresentação',`<form data-form="profile"><label for="name">Nome fictício</label><input id="name" name="name" maxlength="40" value="${esc(me.name)}" required><label for="age">Idade</label><input id="age" name="age" type="number" min="18" max="99" value="${me.age}" required><label for="bio">Sobre você</label><textarea id="bio" name="bio" maxlength="400">${esc(me.bio)}</textarea><button class="primary" type="submit">Salvar</button></form>`);break;
case 'toggle-book':if(me.books.includes(id)){if(me.books.length===1){notify('Mantenha pelo menos um livro.');return;}me.books=me.books.filter(x=>x!==id);}else if(me.books.length<5)me.books.push(id);else{notify('Escolha até cinco livros.');return;}render();break;
case 'pause':paused=!paused;render();break;
case 'project':dialog('Modo demonstração',`<div class="sheet-body"><p>Perfis fictícios. Nada é enviado ou salvo ao sair.</p><p class="muted">Sem login, mensagens reais ou proteção de fotos. Trelelê é o nome escolhido para o app.</p></div>${currentView==='chat'&&activePerson?`<div class="demo-controls"><h3>Testar a conversa</h3><button data-action="simulate-reply">Simular resposta</button><button data-action="simulate-conversation">Avançar 24h e a conversa</button><button data-action="simulate-consent">Simular o outro aceite</button><button data-action="change-photo">Trocar o retrato de teste</button></div>`:''}`,`<button class="outline" data-action="open-studio">Referências e arquivos</button><button class="plain" data-action="reset">Reiniciar demo</button>`);break;
case 'open-studio':closeDialog();go('studio');break;
case 'back-profile':restoreOrigin();break;
case 'back-origin':restoreOrigin();break;
case 'reset':dialog('Recomeçar o teste?',`<p class="sheet-body">Apaga somente os testes temporários desta página.</p>`,`<button class="primary" data-action="reset-confirm">Reiniciar</button><button class="plain" data-action="close">Cancelar</button>`,'',true);break;
case 'reset-confirm':location.hash='discover';location.reload();break;
case 'book':{if(currentView==='people'){const position=$('#main').scrollTop;expandedBook=expandedBook===id?null:id;render();$('#main').scrollTop=position;}break;}

}}catch(error){notify(error.code==='REVEAL_LOCKED'?'Ainda falta tempo ou resposta dos dois. Você pode usar os botões de teste.':'Não foi possível fazer isso agora.');}});
document.addEventListener('input',event=>{if(event.target.id==='message'){const person=event.target.closest('[data-form="chat"]')?.dataset.person;if(person)drafts[person]=event.target.value;}});
document.addEventListener('submit',event=>{const form=event.target;if(!form.dataset.form)return;event.preventDefault();const data=new FormData(form);try{switch(form.dataset.form){case 'chat':{const m=getMatch(state,'you',activePerson);msg(m.id,'you',String(data.get('message')));delete drafts[activePerson];scrollBottomPerson=activePerson;render();$('#message')?.focus();break;}case 'filters':{const min=Number(data.get('min')),max=Number(data.get('max'));if(!Number.isInteger(min)||!Number.isInteger(max)||min<18||max>99||min>max){$('#filter-error').textContent='Escolha idades entre 18 e 99 anos. A idade mínima precisa ser menor ou igual à máxima.';return;}city=String(data.get('city'));ageMin=min;ageMax=max;genre=String(data.get('genre'));bookIndex=0;closeDialog();render();break;}case 'profile':{const age=Number(data.get('age'));if(!Number.isInteger(age)||age<18||age>99)return;me.name=String(data.get('name')).trim()||'Bruno';me.age=age;me.bio=String(data.get('bio')).trim();closeDialog();render();break;}case 'report':{reports.push({id:form.dataset.id,reason:String(data.get('reason'))});if(data.has('block'))block(state,'you',form.dataset.id);closeDialog();go('chat');notify('Registro fictício. Não foi enviado a uma equipe.');break;}}}catch{notify('Não foi possível concluir essa ação.');}});
document.addEventListener('keydown',event=>{if(currentView!=='discover'||discoveryMode!=='for-you'||$('#dialog').open||event.target.closest('input,textarea,select,button,a'))return;const p=currentPerson();if(!p)return;if(event.key==='ArrowRight'){event.preventDefault();bookIndex=(bookIndex+1)%p.books.length;render();}if(event.key==='ArrowLeft'){event.preventDefault();bookIndex=(bookIndex+p.books.length-1)%p.books.length;render();}});
function syncHistory(){
 const frames=modalSnapshots.get(history.state?.treleleModal)??[],target=history.state?.treleleRoute??parseHash();
 if(hashFor(target)!==routeHash()){
   const context=navigationParent&&hashFor(navigationParent.route)===hashFor(target)?navigationParent:null;hideModalUI();savePosition();bookIndex=context?.bookIndex??history.state?.treleleBookIndex??bookIndex;if(context?.route.view==='chat'&&context.route.person&&context.messagesScroll!==null)threadScroll[context.route.person]=context.messagesScroll;applyRoute(target,history.state?.treleleParent??null);render(true);$('#main').scrollTop=context?.rootScroll??history.state?.treleleScroll??scrollPositions[routeHash()]??0;restoreFocus(context);
 }else navigationParent=history.state?.treleleParent??navigationParent;
 if(location.hash!==routeHash()){history.replaceState(routeRecord(false),'',routeHash());modalFrames=[];return;}modalFrames=frames.map(frame=>({...frame}));if(modalFrames.length)displayModal(modalFrames.at(-1));else if($('#dialog').open)$('#dialog').close();
}
window.addEventListener('popstate',()=>{if(ownedPop){const resolve=ownedPop;ownedPop=null;resolve();return;}syncHistory();});
window.addEventListener('hashchange',()=>{if(location.hash!=='#main'&&!historyBusy)syncHistory();});
activePerson=null;route();
